#include <WiFi.h>
#include <WebServer.h>
#include <Update.h>
#include <Wire.h>
#include <Preferences.h>

// =====================================================
// WIFI
// =====================================================

const char* ssid     = "TP-Link S4";
const char* password = "tzp33cs8pu";

// NEW S3 ADDRESS
IPAddress local_IP(192, 168, 68, 142);
IPAddress gateway(192, 168, 68, 1);
IPAddress subnet(255, 255, 255, 0);

// =====================================================
// ESP32-S3 PERMANENT PIN ASSIGNMENTS
// =====================================================

#define INA226_SDA_PIN        8
#define INA226_SCL_PIN        9
#define BATTERY_VOLTAGE_PIN   4

// =====================================================
// INA226
// =====================================================

#define INA226_ADDRESS 0x40

// External shunt:
// 100A @ 75mV
const float SHUNT_OHMS = 0.00075;

// INA226 shunt-voltage resolution:
// 2.5 microvolts per bit
const float INA226_SHUNT_LSB_V = 0.0000025;

// CONFIRMED PHYSICAL POLARITY:
//
// + CURRENT = DISCHARGING
// - CURRENT = CHARGING

// =====================================================
// BATTERY VOLTAGE SENSOR
// =====================================================

// Proven voltage-divider calibration
const float VOLTAGE_DIVIDER_RATIO = 5.038;
const float VOLTAGE_CALIBRATION   = 1.000;

// =====================================================
// BATTERY CONFIGURATION
// =====================================================

const float BATTERY_CAPACITY_AH = 80.0;

// Ignore tiny current around zero
const float CURRENT_DEADBAND_A = 0.01;

// =====================================================
// SERVER / STORAGE
// =====================================================

WebServer server(80);
Preferences preferences;

// =====================================================
// LIVE DATA
// =====================================================

float rawBatteryVoltage = 0.0;
float batteryVoltage    = 0.0;

float shuntVoltage_mV   = 0.0;

float current_A         = 0.0;
float filteredCurrent_A = 0.0;

float power_W = 0.0;

// =====================================================
// PEAKS
// =====================================================

float peakDischarge_A = 0.0;
float peakCharge_A    = 0.0;

// =====================================================
// SESSION
// =====================================================

float sessionUsedAh    = 0.0;
float sessionChargedAh = 0.0;

unsigned long sessionStartMillis = 0;

// =====================================================
// SOC
// =====================================================

bool socSynchronized = false;
float remainingAh    = 0.0;

// =====================================================
// TIMING
// =====================================================

const unsigned long SAMPLE_INTERVAL_MS = 100;
unsigned long lastSampleMillis = 0;

const unsigned long SAVE_INTERVAL_MS = 60000;
unsigned long lastSaveMillis = 0;

// =====================================================
// INA226 REGISTER READ
// =====================================================

bool readINA226Register(uint8_t reg, int16_t &value) {

  Wire.beginTransmission(INA226_ADDRESS);
  Wire.write(reg);

  if (Wire.endTransmission(false) != 0) {
    return false;
  }

  Wire.requestFrom(INA226_ADDRESS, (uint8_t)2);

  if (Wire.available() < 2) {
    return false;
  }

  uint16_t raw =
    ((uint16_t)Wire.read() << 8) |
    Wire.read();

  value = (int16_t)raw;

  return true;
}

// =====================================================
// SHUNT VOLTAGE
// =====================================================

bool readShuntVoltage(float &millivolts) {

  int16_t raw;

  if (!readINA226Register(0x01, raw)) {
    return false;
  }

  float volts =
    raw * INA226_SHUNT_LSB_V;

  millivolts =
    volts * 1000.0;

  return true;
}

// =====================================================
// ADC SORT
// =====================================================

void sortValues(uint32_t values[], int count) {

  for (int i = 0; i < count - 1; i++) {

    for (int j = i + 1; j < count; j++) {

      if (values[j] < values[i]) {

        uint32_t temp = values[i];

        values[i] = values[j];
        values[j] = temp;
      }
    }
  }
}

// =====================================================
// BATTERY VOLTAGE
// =====================================================

float readBatteryVoltage() {

  const int SAMPLE_COUNT = 64;

  uint32_t samples[SAMPLE_COUNT];

  for (int i = 0; i < SAMPLE_COUNT; i++) {

    samples[i] =
      analogReadMilliVolts(
        BATTERY_VOLTAGE_PIN
      );

    delayMicroseconds(150);
  }

  sortValues(samples, SAMPLE_COUNT);

  // Reject lowest/highest 12 samples
  const int FIRST_SAMPLE = 12;
  const int LAST_SAMPLE  = 52;

  uint32_t total = 0;
  int usedSamples = 0;

  for (
    int i = FIRST_SAMPLE;
    i < LAST_SAMPLE;
    i++
  ) {

    total += samples[i];
    usedSamples++;
  }

  float sensorMillivolts =
    total / (float)usedSamples;

  float sensorVolts =
    sensorMillivolts / 1000.0;

  return
    sensorVolts *
    VOLTAGE_DIVIDER_RATIO *
    VOLTAGE_CALIBRATION;
}

// =====================================================
// SAVE SOC
// =====================================================

void saveBatteryState() {

  preferences.begin("battery", false);

  preferences.putBool(
    "synced",
    socSynchronized
  );

  preferences.putFloat(
    "remaining",
    remainingAh
  );

  preferences.end();

  lastSaveMillis = millis();
}

// =====================================================
// LOAD SOC
// =====================================================

void loadBatteryState() {

  preferences.begin("battery", true);

  socSynchronized =
    preferences.getBool(
      "synced",
      false
    );

  remainingAh =
    preferences.getFloat(
      "remaining",
      0.0
    );

  preferences.end();

  if (socSynchronized) {

    remainingAh =
      constrain(
        remainingAh,
        0.0,
        BATTERY_CAPACITY_AH
      );
  }
}

// =====================================================
// SET FULL
// =====================================================

void synchronizeBatteryFull() {

  socSynchronized = true;

  remainingAh =
    BATTERY_CAPACITY_AH;

  sessionUsedAh = 0.0;
  sessionChargedAh = 0.0;

  peakDischarge_A = 0.0;
  peakCharge_A = 0.0;

  sessionStartMillis =
    millis();

  saveBatteryState();
}

// =====================================================
// SOC
// =====================================================

float getSOC() {

  if (!socSynchronized) {
    return 0.0;
  }

  return
    (remainingAh /
     BATTERY_CAPACITY_AH)
    * 100.0;
}

// =====================================================
// UPDATE MONITOR
// =====================================================

void updateBatteryMonitor() {

  unsigned long now = millis();

  if (
    now - lastSampleMillis <
    SAMPLE_INTERVAL_MS
  ) {
    return;
  }

  unsigned long elapsedMs =
    now - lastSampleMillis;

  lastSampleMillis = now;

  // ---------------------------------------------------
  // VOLTAGE
  // ---------------------------------------------------

  rawBatteryVoltage =
    readBatteryVoltage();

  if (batteryVoltage == 0.0) {

    batteryVoltage =
      rawBatteryVoltage;
  }

  else {

    const float VOLTAGE_ALPHA = 0.10;

    batteryVoltage =
      (VOLTAGE_ALPHA *
       rawBatteryVoltage)
      +
      ((1.0 - VOLTAGE_ALPHA) *
       batteryVoltage);
  }

  // ---------------------------------------------------
  // CURRENT
  // ---------------------------------------------------

  float newShunt_mV;

  if (readShuntVoltage(newShunt_mV)) {

    shuntVoltage_mV =
      newShunt_mV;

    float shuntVoltage_V =
      shuntVoltage_mV /
      1000.0;

    current_A =
      shuntVoltage_V /
      SHUNT_OHMS;

    if (
      fabs(current_A) <
      CURRENT_DEADBAND_A
    ) {

      current_A = 0.0;
    }

    // Smooth displayed current
    const float CURRENT_ALPHA = 0.25;

    filteredCurrent_A =
      (CURRENT_ALPHA *
       current_A)
      +
      ((1.0 - CURRENT_ALPHA) *
       filteredCurrent_A);

    // -----------------------------------------------
    // PEAK DISCHARGE
    // Positive current
    // -----------------------------------------------

    if (
      current_A >
      peakDischarge_A
    ) {

      peakDischarge_A =
        current_A;
    }

    // -----------------------------------------------
    // PEAK CHARGE
    // Negative current
    // -----------------------------------------------

    if (current_A < 0.0) {

      float chargeMagnitude =
        -current_A;

      if (
        chargeMagnitude >
        peakCharge_A
      ) {

        peakCharge_A =
          chargeMagnitude;
      }
    }

    // -----------------------------------------------
    // AH INTEGRATION
    // -----------------------------------------------

    float elapsedHours =
      elapsedMs /
      3600000.0;

    float deltaAh =
      current_A *
      elapsedHours;

    // Positive = discharge
    if (current_A > 0.0) {

      sessionUsedAh +=
        deltaAh;
    }

    // Negative = charge
    else if (current_A < 0.0) {

      sessionChargedAh +=
        -deltaAh;
    }

    // -----------------------------------------------
    // SOC
    // -----------------------------------------------

    if (socSynchronized) {

      // + discharge removes Ah
      // - charge adds Ah

      remainingAh -=
        deltaAh;

      remainingAh =
        constrain(
          remainingAh,
          0.0,
          BATTERY_CAPACITY_AH
        );
    }
  }

  // ---------------------------------------------------
  // POWER
  // ---------------------------------------------------

  power_W =
    batteryVoltage *
    filteredCurrent_A;

  // ---------------------------------------------------
  // SAVE SOC
  // ---------------------------------------------------

  if (
    socSynchronized &&
    now - lastSaveMillis >=
    SAVE_INTERVAL_MS
  ) {

    saveBatteryState();
  }
}

// =====================================================
// RESET SESSION
// =====================================================

void resetSession() {

  sessionUsedAh = 0.0;
  sessionChargedAh = 0.0;

  peakDischarge_A = 0.0;
  peakCharge_A = 0.0;

  sessionStartMillis =
    millis();
}

// =====================================================
// RUNTIME
// =====================================================

String formatRuntime() {

  unsigned long seconds =
    (millis() -
     sessionStartMillis)
    / 1000;

  unsigned long hours =
    seconds / 3600;

  unsigned long minutes =
    (seconds % 3600) / 60;

  seconds %= 60;

  char buffer[20];

  snprintf(
    buffer,
    sizeof(buffer),
    "%02lu:%02lu:%02lu",
    hours,
    minutes,
    seconds
  );

  return String(buffer);
}

// =====================================================
// STATUS
// =====================================================

String batteryStatus() {

  if (
    filteredCurrent_A >
    0.10
  ) {

    return "DISCHARGING";
  }

  if (
    filteredCurrent_A <
    -0.10
  ) {

    return "CHARGING";
  }

  return "IDLE";
}

// =====================================================
// RETURN HOME
// =====================================================

void returnHome() {

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303,
    "text/plain",
    ""
  );
}

